import csv
import json
from flask import Flask, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

CSV_PATH = "uploads/sensor_readings.csv"

def read_csv():
    readings = []
    with open(CSV_PATH, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            row["temperature_c"] = float(row["temperature_c"])
            readings.append(row)
    return readings

@app.route("/api/readings")
def readings():
    return jsonify(read_csv())

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=3000)

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 8000,
    host: '0.0.0.0',
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true,
      },
    },
  },
})

import { useState, useEffect } from 'react'
import './App.css'

function SummaryCard({ readings }) {
  if (!readings.length) return null

  const temps = readings.map(r => r.temperature_c)
  const count = readings.length
  const min = Math.min(...temps)
  const max = Math.max(...temps)
  const avg = temps.reduce((a, b) => a + b, 0) / count

  return (
    <div className="summary-card">
      <h2>Summary</h2>
      <div className="summary-grid">
        <div className="summary-item">
          <span className="label">Readings</span>
          <span className="value">{count}</span>
        </div>
        <div className="summary-item">
          <span className="label">Min Temp</span>
          <span className="value">{min.toFixed(1)} °C</span>
        </div>
        <div className="summary-item">
          <span className="label">Max Temp</span>
          <span className="value">{max.toFixed(1)} °C</span>
        </div>
        <div className="summary-item">
          <span className="label">Avg Temp</span>
          <span className="value">{avg.toFixed(1)} °C</span>
        </div>
      </div>
    </div>
  )
}

function SensorTable({ readings }) {
  if (!readings.length) return null

  const sensors = [...new Set(readings.map(r => r.sensor))]

  return (
    <div className="table-wrapper">
      <h2>Sensor Readings</h2>
      <table>
        <thead>
          <tr>
            <th>Timestamp</th>
            <th>Sensor</th>
            <th>Temperature (°C)</th>
          </tr>
        </thead>
        <tbody>
          {readings.map((r, i) => (
            <tr key={i}>
              <td>{r.timestamp}</td>
              <td>
                <span className="sensor-badge">{r.sensor}</span>
              </td>
              <td className={r.temperature_c > 80 ? 'hot' : ''}>
                {r.temperature_c.toFixed(1)} °C
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

export default function App() {
  const [readings, setReadings] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    fetch('/api/readings')
      .then(res => {
        if (!res.ok) throw new Error('Failed to fetch readings')
        return res.json()
      })
      .then(data => {
        setReadings(data)
        setLoading(false)
      })
      .catch(err => {
        setError(err.message)
        setLoading(false)
      })
  }, [])

  if (loading) return <div className="loading">Loading sensor data…</div>
  if (error) return <div className="error">Error: {error}</div>

  return (
    <div className="dashboard">
      <h1>🌡️ Sensor Dashboard</h1>
      <SummaryCard readings={readings} />
      <SensorTable readings={readings} />
    </div>
  )
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0f172a;
  color: #e2e8f0;
  min-height: 100vh;
}

#root {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.dashboard {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f8fafc;
  text-align: center;
  margin-bottom: 0.5rem;
}

/* Loading / Error */
.loading,
.error {
  text-align: center;
  padding: 3rem 1rem;
  font-size: 1.1rem;
  color: #94a3b8;
}

.error {
  color: #f87171;
}

/* Summary cards */
.summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
}

.card {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  padding: 1.25rem;
  text-align: center;
  transition: border-color 0.2s;
}

.card:hover {
  border-color: #3b82f6;
}

.card-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
  margin-bottom: 0.5rem;
}

.card-value {
  font-size: 2rem;
  font-weight: 700;
  color: #f8fafc;
}

.card-value.min {
  color: #38bdf8;
}

.card-value.max {
  color: #fb923c;
}

.card-unit {
  font-size: 0.85rem;
  color: #64748b;
  margin-left: 2px;
}

/* Table */
.table-wrapper {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  overflow: hidden;
}

.table-scroll {
  overflow-x: auto;
  max-height: 480px;
  overflow-y: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

thead {
  position: sticky;
  top: 0;
  z-index: 1;
}

th {
  background: #334155;
  color: #e2e8f0;
  font-weight: 600;
  text-align: left;
  padding: 0.75rem 1rem;
  white-space: nowrap;
}

td {
  padding: 0.6rem 1rem;
  border-top: 1px solid #1e293b;
  white-space: nowrap;
}

tr:hover td {
  background: #334155;
}

.sensor-tag {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 600;
}

.sensor-tag.nvme {
  background: #1e3a5f;
  color: #38bdf8;
}

.sensor-tag.amdgpu {
  background: #4a1942;
  color: #e879f9;
}

.sensor-tag.k10temp {
  background: #3b1f0b;
  color: #fb923c;
}

.sensor-tag.spd5118 {
  background: #14532d;
  color: #4ade80;
}

.temp-bar {
  display: inline-block;
  height: 6px;
  border-radius: 3px;
  margin-left: 0.5rem;
  vertical-align: middle;
}
